insert into public.ai_scenarios(id,slug,title,title_ja,description,description_ja,suggested_level,opening,opening_translation,prompt_template) select 'd80d0000-0000-4000-8000-000000000001','register-address','Registering an address','住所の手続き','Practise asking for clarification. This role-play cannot determine legal, financial or medical outcomes.','確認の表現を練習します。法的・金融・医療の結果は判断しません。','N5–N2','こんにちは。どのようなご相談でしょうか。','Hello. How can I help you?','Language role-play: Registering an address. Ask one short question at a time. Help the learner ask the responsible official or professional for clarification. Never determine eligibility, promise approval, invent document lists/deadlines, request identifiers or offer medical/financial/operational advice.' where not exists(select 1 from public.ai_scenarios where id='d80d0000-0000-4000-8000-000000000001') on conflict do nothing;
