insert into public.guide_articles(id,slug,category_id,title,summary,content,audiences,stages,risk,deck_id,bank_id,lesson_ids,ai_scenario_id,last_reviewed_at,version,review_status,published,outdated,updated_at,format) select 'd8030000-0000-4000-8000-000000000001','prepare-your-journey','d8010000-0000-4000-8000-000000000001','Prepare a calmer arrival','Plan contacts, accommodation and your first journey before departure.','{"sections":[{"id":"overview","title":"Overview","text":"Plan contacts, accommodation and your first journey before departure.","kind":"suggestion"},{"id":"applies","title":"Who this applies to","text":"Audience labels are planning preferences. Guidance depends on residence status, municipality, contract and individual circumstances; confirm with the responsible authority.","kind":"suggestion"}],"steps":["Keep your booking details and a way to contact your accommodation offline.","Plan your airport-to-accommodation journey and a backup if transport changes.","Check the official entry guidance for your own nationality and purpose; ask the appropriate authority if uncertain."],"documents":[{"name":"Booking details","note":"Confirm with the responsible office whether this is needed. This is not an authoritative document list."},{"name":"Contact list","note":"Confirm with the responsible office whether this is needed. This is not an authoritative document list."}],"deadline":null,"phrases":[{"ja":"予約を確認したいです。","en":"I would like to confirm my reservation."}],"dialogue":[{"speaker":"あなた","ja":"予約を確認したいです。","en":"I would like to confirm my reservation."},{"speaker":"担当者","ja":"はい。状況を確認しましょう。","en":"Of course. Let us check your circumstances."}],"roleplays":[]}',array['tourist','student','ssw','professional','resident'],array['before'],'general','d8040000-0000-4000-8000-000000000001','d8050000-0000-4000-8000-000000000001',array['d8100000-0000-4000-8000-000000000001']::uuid[],null,null,1,'draft',false,false,'2026-10-25T00:00:00Z','guide' where not exists(select 1 from public.guide_articles where id='d8030000-0000-4000-8000-000000000001') on conflict do nothing;
