insert into public.guide_articles(id,slug,category_id,title,summary,content,audiences,stages,risk,deck_id,bank_id,lesson_ids,ai_scenario_id,last_reviewed_at,version,review_status,published,outdated,updated_at,format) select 'd8030000-0000-4000-8000-000000000002','city-hall-first-visit','d8010000-0000-4000-8000-000000000002','Plan your first city-hall visit','Find the right counter and ask which procedures apply to you.','{"sections":[{"id":"overview","title":"Overview","text":"Find the right counter and ask which procedures apply to you.","kind":"municipal"},{"id":"applies","title":"Who this applies to","text":"Audience labels are planning preferences. Guidance depends on residence status, municipality, contract and individual circumstances; confirm with the responsible authority.","kind":"municipal"}],"steps":["Find your municipality''s official office information and language support.","Explain your arrival and living situation without assuming every procedure applies.","Ask staff to confirm the documents, appointment arrangements and any applicable deadline before you leave."],"documents":[{"name":"Documents specifically requested by the municipal office","note":"Confirm with the responsible office whether this is needed. This is not an authoritative document list."},{"name":"Your own questions","note":"Confirm with the responsible office whether this is needed. This is not an authoritative document list."}],"deadline":null,"phrases":[{"ja":"住所の手続きは、どの窓口ですか。","en":"Which counter handles address procedures?"}],"dialogue":[{"speaker":"あなた","ja":"住所の手続きは、どの窓口ですか。","en":"Which counter handles address procedures?"},{"speaker":"担当者","ja":"はい。状況を確認しましょう。","en":"Of course. Let us check your circumstances."}],"roleplays":[{"slug":"register-address","title":"Registering an address","title_ja":"住所の手続き","scenario_id":"d80d0000-0000-4000-8000-000000000001","dialogue":[{"speaker":"担当者","ja":"こんにちは。どのようなご相談でしょうか。","en":"Hello. How can I help you?"},{"speaker":"あなた","ja":"住所の手続きについて質問したいです。","en":"I would like to ask about address procedures."},{"speaker":"担当者","ja":"状況を確認しましょう。","en":"Let us check the circumstances."}]}]}',array['student','ssw','professional','resident'],array['arriving','settling'],'administrative','d8040000-0000-4000-8000-000000000002','d8050000-0000-4000-8000-000000000002',array['d8100000-0000-4000-8000-000000000002']::uuid[],'d80d0000-0000-4000-8000-000000000001',null,1,'draft',false,false,'2026-10-25T00:00:00Z','guide' where not exists(select 1 from public.guide_articles where id='d8030000-0000-4000-8000-000000000002') on conflict do nothing;
