insert into public.guide_articles(id,slug,category_id,title,summary,content,audiences,stages,risk,deck_id,bank_id,lesson_ids,ai_scenario_id,last_reviewed_at,version,review_status,published,outdated,updated_at,format) select 'd8030000-0000-4000-8000-000000000006','prepare-for-a-clinic-visit','d8010000-0000-4000-8000-000000000006','Prepare for a clinic visit','Prepare a short explanation and confirm the clinic''s arrangements.','{"sections":[{"id":"overview","title":"Overview","text":"Prepare a short explanation and confirm the clinic''s arrangements.","kind":"suggestion"},{"id":"applies","title":"Who this applies to","text":"Audience labels are planning preferences. Guidance depends on residence status, municipality, contract and individual circumstances; confirm with the responsible authority.","kind":"suggestion"}],"steps":["For a planned visit, confirm the clinic''s hours, language support, appointment and payment arrangements.","Prepare a short description of your concern and any information a qualified clinician asks for; do not enter private medical details in this app.","Ask the provider or insurer what evidence of coverage is accepted now. For urgent help, use official emergency services rather than this learning page."],"documents":[{"name":"Items the clinic asks you to bring","note":"Confirm with the responsible office whether this is needed. This is not an authoritative document list."},{"name":"Insurance or payment questions for the provider","note":"Confirm with the responsible office whether this is needed. This is not an authoritative document list."}],"deadline":null,"phrases":[{"ja":"予約が必要ですか。","en":"Do I need an appointment?"}],"dialogue":[{"speaker":"あなた","ja":"予約が必要ですか。","en":"Do I need an appointment?"},{"speaker":"担当者","ja":"はい。状況を確認しましょう。","en":"Of course. Let us check your circumstances."}],"roleplays":[{"slug":"visit-clinic","title":"Visiting a clinic","title_ja":"診療所で話す","scenario_id":"d80d0000-0000-4000-8000-000000000006","dialogue":[{"spea