insert into public.guide_articles(id,slug,category_id,title,summary,content,audiences,stages,risk,deck_id,bank_id,lesson_ids,ai_scenario_id,last_reviewed_at,version,review_status,published,outdated,updated_at,format) select 'd8030000-0000-4000-8000-000000000007','plan-your-daily-journey','d8010000-0000-4000-8000-000000000007','Plan your daily journey','Check your route, signs and operator guidance before travelling.','{"sections":[{"id":"overview","title":"Overview","text":"Check your route, signs and operator guidance before travelling.","kind":"culture"},{"id":"applies","title":"Who this applies to","text":"Audience labels are planning preferences. Guidance depends on residence status, municipality, contract and individual circumstances; confirm with the responsible authority.","kind":"culture"}],"steps":["Check your destination, route and last connection with the transport operator.","Follow posted boarding directions, keep access clear and ask staff if a sign is unclear.","For walking or cycling, check current official road rules and local signs. Etiquette suggestions are different from traffic laws."],"documents":[{"name":"Your route and destination details","note":"Confirm with the responsible office whether this is needed. This is not an authoritative document list."}],"deadline":null,"phrases":[{"ja":"この電車は、ここに止まりますか。","en":"Does this train stop here?"}],"dialogue":[{"speaker":"あなた","ja":"この電車は、ここに止まりますか。","en":"Does this train stop here?"},{"speaker":"担当者","ja":"はい。状況を確認しましょう。","en":"Of course. Let us check your circumstances."}],"roleplays":[{"slug":"ask-directions","title":"Asking for directions","title_ja":"道を尋ねる","scenario_id":"d80d0000-0000-4000-8000-000000000004","dialogue":[{"speaker":"担当者","ja":"こんにちは。どのようなご相談でしょうか。","en":"Hello. How can I help you?"},{"speaker":"あなた","ja":"すみません、駅の出口はどちらですか。","en":"Excuse me, which way is the station exit?"},{"speaker":"担当者","ja":"状況を確認しましょう。","en":"Let us check the circumstances."}]}]}',array['tourist','student','