insert into public.guide_articles(id,slug,category_id,title,summary,content,audiences,stages,risk,deck_id,bank_id,lesson_ids,ai_scenario_id,last_reviewed_at,version,review_status,published,outdated,updated_at,format) select 'd8030000-0000-4000-8000-000000000010','prepare-for-disruptions','d8010000-0000-4000-8000-000000000010','Prepare for emergencies and disruptions','Know where official information and local help can be found.','{"sections":[{"id":"overview","title":"Overview","text":"Know where official information and local help can be found.","kind":"suggestion"},{"id":"applies","title":"Who this applies to","text":"Audience labels are planning preferences. Guidance depends on residence status, municipality, contract and individual circumstances; confirm with the responsible authority.","kind":"suggestion"}],"steps":["Read your accommodation''s emergency information and locate the indicated evacuation routes.","Find your municipality''s official disaster information and decide how to receive current alerts.","Agree a contact plan with people you trust. During an incident, follow current official instructions and qualified local staff, not a saved learning example."],"documents":[{"name":"Your private emergency contact plan","note":"Confirm with the responsible office whether this is needed. This is not an authoritative document list."},{"name":"Official local evacuation information","note":"Confirm with the responsible office whether this is needed. This is not an authoritative document list."}],"deadline":null,"phrases":[{"ja":"避難する場所はどこですか。","en":"Where is the evacuation location?"}],"dialogue":[{"speaker":"あなた","ja":"避難する場所はどこですか。","en":"Where is the evacuation location?"},{"speaker":"担当者","ja":"はい。状況を確認しましょう。","en":"Of course. Let us check your circumstances."}],"roleplays":[]}',array['tourist','student','ssw','professional','resident'],array['before','arriving','settling'],'safety','d8040000-0000-4000-8000-000000000010','d8050000-0000-4000-8000-000000000010',array['d8100000-0000-4000-8000-000000000010']::uuid[],null,null,1,'draft',false,false,'2026-10-25T00:00:00Z','guide' where not exists(select 1 from public.guide_articles where id='d8030000-0000-4000-8000-000000000010') on conflict do nothing;
