insert into public.guide_translations(id,article_id,locale,title,summary,content,review_status,updated_at) select 'd8060000-0000-4000-8000-000000000001','d8030000-0000-4000-8000-000000000001','ja','安心して来日するために','出発前に連絡先、宿泊先、最初の移動を整理します。','{"sections":[{"id":"overview","title":"概要","text":"出発前に連絡先、宿泊先、最初の移動を整理します。","kind":"suggestion"},{"id":"applies","title":"対象と確認先","text":"対象は選んだ学習目的の目安です。在留資格、自治体、契約、個別の状況によって案内が変わります。担当の公式機関に確認してください。","kind":"suggestion"}],"steps":["予約の内容と宿泊先への連絡方法を、通信がなくても見られるようにします。","空港から宿泊先までの移動と、交通が変わった場合の代案を考えます。","国籍と目的に合う入国案内を公式機関で確認し、不明な点を問い合わせます。"],"documents":[{"name":"予約の内容","note":"持参が必要か担当者に確認してください。これは確定した必要書類一覧ではありません。"},{"name":"連絡先一覧","note":"持参が必要か担当者に確認してください。これは確定した必要書類一覧ではありません。"}],"deadline":null,"phrases":[{"ja":"予約を確認したいです。","en":"I would like to confirm my reservation."}],"dialogue":[{"speaker":"あなた","ja":"予約を確認したいです。","en":"I would like to confirm my reservation."},{"speaker":"担当者","ja":"はい。状況を確認しましょう。","en":"Of course. Let us check your circumstances."}],"roleplays":[]}','draft','2026-10-25T00:00:00Z' where not exists(select 1 from public.guide_translations where id='d8060000-0000-4000-8000-000000000001') on conflict do nothing;
insert into public.guide_translations(id,article_id,locale,title,summary,content,review_status,updated_at) select 'd8060000-0000-4000-8000-000000000002','d8030000-0000-4000-8000-000000000002','ja','市役所への最初の訪問','担当窓口を調べ、自分に必要な手続きを確認します。','{"sections":[{"id":"overview","title":"概要","text":"担当窓口を調べ、自分に必要な手続きを確認します。","kind":"municipal"},{"id":"applies","title":"対象と確認先","text":"対象は選んだ学習目的の目安です。在留資格、自治体、契約、個別の状況によって案内が変わります。担当の公式機関に確認してください。","kind":"municipal"}],"steps":["住む自治体の公式な窓口情報と通訳などの支援を調べます。","来日や生活の状況を説明します。すべての手続きが必要とは限りません。","必要な書類、予約の要否、該当する期限を担当者に確認します。"],"documents":[{"name":"自治体の窓口から案内された書類","note":"持参が必要か担当者に確認してください。これは確定した必要書類一覧ではありません。"},{"name":"質問のメモ","note":"持参が必要か担当者に確認してください。これは確定した必要書類一覧ではありません。"}],"deadline":null,"phrases":[{"ja":"住所の手続きは、どの窓口ですか。","en":"Which counter handles address procedures?"}],"dialogue":[{"speaker":"あなた","ja":"住所の手続きは、どの窓口ですか。","en":"Which counter handles address procedures?"},{"speaker":"担当者","ja":"はい。状況を確認しましょう。","en":"Of course. Let us check your circumstances."}],"roleplays":[{"slug":"register-address","title":"Registering an address","title_ja":"住所の手続き","scenario_id":"d80d0000-0000-4000-8000-000000000001","dialogue":[{"speaker":"担当者","ja":"こんにちは。どのようなご相談でしょうか。","en":"Hello. How can I help you?"},{"speaker":"あなた","ja":"住所の手続きについて質問したいです。","en":"I would like to ask about address procedures."},{"speaker":"担当者","ja":"状況を確認しましょう。","en":"Let us check the circumstances."}]}]}','draft','2026-10-25T00:00:00Z' where not exists(select 1 from public.guide_translations where id='d8060000-0000-4000-8000-000000000002') on conflict do nothing;
insert into public.guide_translations(id,article_id,locale,title,summary,content,review_status,updated_at) select 'd8060000-0000-4000-8000-000000000003','d8030000-0000-4000-8000-000000000003','ja','必要な書類を確認する','自分の申請や手続きに合う公式の案内を確認します。','{"sections":[{"id":"overview","title":"概要","text":"自分の申請や手続きに合う公式の案内を確認します。","kind":"law"},{"id":"applies","title":"対象と確認先","text":"対象は選んだ学習目的の目安です。在留資格、自治体、契約、個別の状況によって案内が変わります。担当の公式機関に確認してください。","kind":"law"}],"steps":["どの手続きなのか、担当する公式機関はどこかを確かめます。","最新の公式案内を読み、個別の事情で変わる点を問い合わせます。","原本・写し・期限を担当機関に確認します。このチェックリストは資格の有無を判断しません。"],"documents":[{"name":"担当機関の最新の必要書類一覧","note":"持参が必要か担当者に確認してください。これは確定した必要書類一覧ではありません。"},{"name":"担当機関が求める場合の写し","note":"持参が必要か担当者に確認してください。これは確定した必要書類一覧ではありません。"}],"deadline":null,"phrases":[{"ja":"必要な書類を教えていただけますか。","en":"Could you tell me which documents are needed?"}],"dialogue":[{"speaker":"あなた","ja":"必要な書類を教えていただけますか。","en":"Could you tell me which documents are needed?"},{"speaker":"担当者","ja":"はい。状況を確認しましょう。","en":"Of course. Let us check your circumstances."}],"roleplays":[]}','draft','2026-10-25T00:00:00Z' where not exists(select 1 from public.guide_translations where id='d8060000-0000-4000-8000-000000000003') on conflict do nothing;
insert into public.guide_translations(id,article_id,locale,title,summary,content,review_status,updated_at) select 'd8060000-0000-4000-8000-000000000004','d8030000-0000-4000-8000-000000000004','ja','住まいの条件を確認する','住まいの契約条件と設備の手続きを担当者に確認します。','{"sections":[{"id":"overview","title":"概要","text":"住まいの契約条件と設備の手続きを担当者に確認します。","kind":"suggestion"},{"id":"applies","title":"対象と確認先","text":"対象は選んだ学習目的の目安です。在留資格、自治体、契約、個別の状況によって案内が変わります。担当の公式機関に確認してください。","kind":"suggestion"}],"steps":["学校、宿泊先の担当者、不動産会社に住まいや支援について尋ねます。","同意する前に、自分の契約、費用、建物のルール、入居時の状態確認を説明してもらいます。","電気・ガス・水道・インターネットを誰が手配するか、予約や本人確認の要件を確認します。"],"documents":[{"name":"検討中または現在の住まいの契約","note":"持参が必要か担当者に確認してください。これは確定した必要書類一覧ではありません。"},{"name":"各事業者が求める情報","note":"持参が必要か担当者に確認してください。これは確定した必要書類一覧ではありません。"}],"deadline":null,"phrases":[{"ja":"この費用について、説明していただけますか。","en":"Could you explain this charge?"}],"dialogue":[{"speaker":"あなた","ja":"この費用について、説明していただけますか。","en":"Could you explain this charge?"},{"speaker":"担当者","ja":"はい。状況を確認しましょう。","en":"Of course. Let us check your circumstances."}],"roleplays":[{"slug":"talk-landlord","title":"Talking to a landlord","title_ja":"住まいの担当者と話す","scenario_id":"d80d0000-0000-4000-8000-000000000005","dialogue":[{"speaker":"担当者","ja":"こんにちは。どのようなご相談でしょうか。","en":"Hello. How can I help you?"},{"speaker":"あなた","ja":"契約について、確認したいことがあります。","en":"I have a question about the contract."},{"speaker":"担当者","ja":"状況を確認しましょう。","en":"Let us check the circumstances."}]}]}','draft','2026-10-25T00:00:00Z' where not exists(select 1 from public.guide_translations where id='d8060000-0000-4000-8000-000000000004') on conflict do nothing;
insert into public.guide_translations(id,article_id,locale,title,summary,content,review_status,updated_at) select 'd8060000-0000-4000-8000-000000000005','d8030000-0000-4000-8000-000000000005','ja','お金と保険の質問を整理する','銀行・税金・保険・年金について担当機関に確認します。','{"sections":[{"id":"overview","title":"概要","text":"銀行・税金・保険・年金について担当機関に確認します。","kind":"law"},{"id":"applies","title":"対象と確認先","text":"対象は選んだ学習目的の目安です。在留資格、自治体、契約、個別の状況によって案内が変わります。担当の公式機関に確認してください。","kind":"law"}],"steps":["銀行や携帯電話会社に、自分の状況で利用できるサービスと本人確認を尋ねます。要件は異なります。","勤務先や自治体に、自分に該当する医療保険や年金の手続きを確認します。","分からない税の通知や期限は担当窓口に尋ねる予定を記録します。金融関係の書類をこのサイトに送らないでください。"],"documents":[{"name":"事業者の最新の必要書類一覧","note":"持参が必要か担当者に確認してください。これは確定した必要書類一覧ではありません。"},{"name":"通知についての質問（書類のアップロードは不要）","note":"持参が必要か担当者に確認してください。これは確定した必要書類一覧ではありません。"}],"deadline":null,"phrases":[{"ja":"私の場合、どの手続きが必要ですか。","en":"Which procedures are needed in my situation?"}],"dialogue":[{"speaker":"あなた","ja":"私の場合、どの手続きが必要ですか。","en":"Which procedures are needed in my situation?"},{"speaker":"担当者","ja":"はい。状況を確認しましょう。","en":"Of course. Let us check your circumstances."}],"roleplays":[{"slug":"ask-insurance","title":"Asking about health insurance","title_ja":"医療保険について尋ねる","scenario_id":"d80d0000-0000-4000-8000-000000000002","dialogue":[{"speaker":"担当者","ja":"こんにちは。どのようなご相談でしょうか。","en":"Hello. How can I help you?"},{"speaker":"あなた","ja":"私の場合、保険の相談はどこでできますか。","en":"Where can I ask about insurance in my circumstances?"},{"speaker":"担当者","ja":"状況を確認しましょう。","en":"Let us check the circumstances."}]},{"slug":"open-bank-account","title":"Opening a bank account","title_ja":"銀行口座について尋ねる","scenario_id":"d80d0000-0000-4000-8000-000000000003","dialogue":[{"speaker":"担当者","ja":"こんにちは。どのようなご相談でしょうか。","en":"Hello. How can I help you?"},{"speaker":"あなた","ja":"口座について、必要な書類を教えていただけますか。","en":"Could you tell me which documents are needed for an account?"},{"speaker":"担当者","ja":"状況を確認しましょう。","en":"Let us check the circumstances."}]}]}','draft','2026-10-25T00:00:00Z' where not exists(select 1 from public.guide_translations where id='d8060000-0000-4000-8000-000000000005') on conflict do nothing;
insert into public.guide_translations(id,article_id,locale,title,summary,content,review_status,updated_at) select 'd8060000-0000-4000-8000-000000000006','d8030000-0000-4000-8000-000000000006','ja','診療所への訪問を準備する','症状を伝える言葉を準備し、医療機関の案内を確認します。','{"sections":[{"id":"overview","title":"概要","text":"症状を伝える言葉を準備し、医療機関の案内を確認します。","kind":"suggestion"},{"id":"applies","title":"対象と確認先","text":"対象は選んだ学習目的の目安です。在留資格、自治体、契約、個別の状況によって案内が変わります。担当の公式機関に確認してください。","kind":"suggestion"}],"steps":["予定の受診では、診療時間、言語支援、予約、支払い方法を確認します。","困っていることを短く説明する準備をし、医療者が求める情報を用意します。個人的な医療情報をこのサイトに入力しないでください。","現在受け付ける保険資格の確認方法を医療機関や保険者に確認します。緊急時は学習ページではなく公的な緊急支援を利用してください。"],"documents":[{"name":"医療機関が持参を求めるもの","note":"持参が必要か担当者に確認してください。これは確定した必要書類一覧ではありません。"},{"name":"保険や支払いについての質問","note":"持参が必要か担当者に確認してください。これは確定した必要書類一覧ではありません。"}],"deadline":null,"phrases":[{"ja":"予約が必要ですか。","en":"Do I need an appointment?"}],"dialogue":[{"speaker":"あなた","ja":"予約が必要ですか。","en":"Do I need an appointment?"},{"speaker":"担当者","ja":"はい。状況を確認しましょう。","en":"Of course. Let us check your circumstances."}],"roleplays":[{"slug":"visit-clinic","title":"Visiting a clinic","title_ja":"診療所で話す","scenario_id":"d80d0000-0000-4000-8000-000000000006","dialogue":[{"speaker":"担当者","ja":"こんにちは。どのようなご相談でしょうか。","en":"Hello. How can I help you?"},{"speaker":"あなた","ja":"予約の方法を教えてください。","en":"Please explain how to make an appointment."},{"speaker":"担当者","ja":"状況を確認しましょう。","en":"Let us check the circumstances."}]}]}','draft','2026-10-25T00:00:00Z' where not exists(select 1 from public.guide_translations where id='d8060000-0000-4000-8000-000000000006') on conflict do nothing;
insert into public.guide_translations(id,article_id,locale,title,summary,content,review_status,updated_at) select 'd8060000-0000-4000-8000-000000000007','d8030000-0000-4000-8000-000000000007','ja','毎日の移動を考える','移動前に経路、案内表示、交通機関の案内を確認します。','{"sections":[{"id":"overview","title":"概要","text":"移動前に経路、案内表示、交通機関の案内を確認します。","kind":"culture"},{"id":"applies","title":"対象と確認先","text":"対象は選んだ学習目的の目安です。在留資格、自治体、契約、個別の状況によって案内が変わります。担当の公式機関に確認してください。","kind":"culture"}],"steps":["目的地、経路、最終の乗り継ぎを交通機関の案内で確認します。","乗車の案内に従い、通路をふさがず、分からない表示は係員に尋ねます。","徒歩や自転車では、現在の公式の交通ルールと現地の標識を確認します。マナーと法律は区別します。"],"documents":[{"name":"経路と目的地の情報","note":"持参が必要か担当者に確認してください。これは確定した必要書類一覧ではありません。"}],"deadline":null,"phrases":[{"ja":"この電車は、ここに止まりますか。","en":"Does this train stop here?"}],"dialogue":[{"speaker":"あなた","ja":"この電車は、ここに止まりますか。","en":"Does this train stop here?"},{"speaker":"担当者","ja":"はい。状況を確認しましょう。","en":"Of course. Let us check your circumstances."}],"roleplays":[{"slug":"ask-directions","title":"Asking for directions","title_ja":"道を尋ねる","scenario_id":"d80d0000-0000-4000-8000-000000000004","dialogue":[{"speaker":"担当者","ja":"こんにちは。どのようなご相談でしょうか。","en":"Hello. How can I help you?"},{"speaker":"あなた","ja":"すみません、駅の出口はどちらですか。","en":"Excuse me, which way is the station exit?"},{"speaker":"担当者","ja":"状況を確認しましょう。","en":"Let us check the circumstances."}]}]}','draft','2026-10-25T00:00:00Z' where not exists(select 1 from public.guide_translations where id='d8060000-0000-4000-8000-000000000007') on conflict do nothing;
insert into public.guide_translations(id,article_id,locale,title,summary,content,review_status,updated_at) select 'd8060000-0000-4000-8000-000000000008','d8030000-0000-4000-8000-000000000008','ja','職場の説明を受ける準備','作業の前に、質問先と指示の確認方法を学びます。','{"sections":[{"id":"overview","title":"概要","text":"作業の前に、質問先と指示の確認方法を学びます。","kind":"workplace"},{"id":"applies","title":"対象と確認先","text":"対象は選んだ学習目的の目安です。在留資格、自治体、契約、個別の状況によって案内が変わります。担当の公式機関に確認してください。","kind":"workplace"}],"steps":["研修、言語支援、作業に必要な安全教育の担当者を上司に確認します。","初めての作業では、担当の有資格者などに実演を求め、理解が合っているか確かめます。","不明点や心配なことの報告先を調べます。この日本語練習は安全資格や機械の操作許可ではありません。"],"documents":[{"name":"勤務先の研修案内","note":"持参が必要か担当者に確認してください。これは確定した必要書類一覧ではありません。"},{"name":"上司への質問","note":"持参が必要か担当者に確認してください。これは確定した必要書類一覧ではありません。"}],"deadline":null,"phrases":[{"ja":"分からないので、もう一度教えてください。","en":"I do not understand; please explain again."}],"dialogue":[{"speaker":"あなた","ja":"分からないので、もう一度教えてください。","en":"I do not understand; please explain again."},{"speaker":"担当者","ja":"はい。状況を確認しましょう。","en":"Of course. Let us check your circumstances."}],"roleplays":[{"slug":"speak-supervisor","title":"Speaking with a supervisor","title_ja":"上司に確認する","scenario_id":"d80d0000-0000-4000-8000-000000000007","dialogue":[{"speaker":"担当者","ja":"こんにちは。どのようなご相談でしょうか。","en":"Hello. How can I help you?"},{"speaker":"あなた","ja":"作業の前に、もう一度確認してもよろしいですか。","en":"May I check once more before starting the task?"},{"speaker":"担当者","ja":"状況を確認しましょう。","en":"Let us check the circumstances."}]}]}','draft','2026-10-25T00:00:00Z' where not exists(select 1 from public.guide_translations where id='d8060000-0000-4000-8000-000000000008') on conflict do nothing;
insert into public.guide_translations(id,article_id,locale,title,summary,content,review_status,updated_at) select 'd8060000-0000-4000-8000-000000000009','d8030000-0000-4000-8000-000000000009','ja','ルールの違いを理解する','法律、地域のルール、職場の方針、配慮の習慣を区別します。','{"sections":[{"id":"overview","title":"概要","text":"法律、地域のルール、職場の方針、配慮の習慣を区別します。","kind":"culture"},{"id":"applies","title":"対象と確認先","text":"対象は選んだ学習目的の目安です。在留資格、自治体、契約、個別の状況によって案内が変わります。担当の公式機関に確認してください。","kind":"culture"}],"steps":["掲示の発信元が自治体、交通機関、勤務先、施設のどこかを確かめます。","どこでも同じと思い込まず、その場所での意味を尋ねます。","短い文化レッスンで配慮のある対応を練習します。一般的な習慣が法律上の義務とは限りません。"],"documents":[{"name":"自分で確認する現地の掲示や案内","note":"持参が必要か担当者に確認してください。これは確定した必要書類一覧ではありません。"}],"deadline":null,"phrases":[{"ja":"こちらのルールを教えてください。","en":"Please explain the rules here."}],"dialogue":[{"speaker":"あなた","ja":"こちらのルールを教えてください。","en":"Please explain the rules here."},{"speaker":"担当者","ja":"はい。状況を確認しましょう。","en":"Of course. Let us check your circumstances."}],"roleplays":[]}','draft','2026-10-25T00:00:00Z' where not exists(select 1 from public.guide_translations where id='d8060000-0000-4000-8000-000000000009') on conflict do nothing;
insert into public.guide_translations(id,article_id,locale,title,summary,content,review_status,updated_at) select 'd8060000-0000-4000-8000-000000000010','d8030000-0000-4000-8000-000000000010','ja','緊急時や災害に備える','公式情報と地域の支援先を確認しておきます。','{"sections":[{"id":"overview","title":"概要","text":"公式情報と地域の支援先を確認しておきます。","kind":"suggestion"},{"id":"applies","title":"対象と確認先","text":"対象は選んだ学習目的の目安です。在留資格、自治体、契約、個別の状況によって案内が変わります。担当の公式機関に確認してください。","kind":"suggestion"}],"steps":["宿泊先や住まいの緊急時の案内を読み、示された避難経路を確認します。","自治体の公式な防災情報と、最新の警報を受け取る方法を調べます。","信頼できる人と連絡方法を決めます。災害時は保存した例文ではなく、最新の公式指示や現地の担当者の案内に従います。"],"documents":[{"name":"自分で保管する緊急連絡の計画","note":"持参が必要か担当者に確認してください。これは確定した必要書類一覧ではありません。"},{"name":"地域の公式な避難情報","note":"持参が必要か担当者に確認してください。これは確定した必要書類一覧ではありません。"}],"deadline":null,"phrases":[{"ja":"避難する場所はどこですか。","en":"Where is the evacuation location?"}],"dialogue":[{"speaker":"あなた","ja":"避難する場所はどこですか。","en":"Where is the evacuation location?"},{"speaker":"担当者","ja":"はい。状況を確認しましょう。","en":"Of course. Let us check your circumstances."}],"roleplays":[]}','draft','2026-10-25T00:00:00Z' where not exists(select 1 from public.guide_translations where id='d8060000-0000-4000-8000-000000000010') on conflict do nothing;
insert into public.guide_translations(id,article_id,locale,title,summary,content,review_status,updated_at) select 'd8060000-0000-4000-8000-000000000011','d8030000-0000-4000-8000-000000000011','ja','公共交通のマナー','通路をふさがず、交通機関の掲示に従います。会話や携帯電話の利用では周りの人に配慮します。','{"sections":[{"id":"lesson","title":"公共交通のマナー","text":"通路をふさがず、交通機関の掲示に従います。会話や携帯電話の利用では周りの人に配慮します。","kind":"culture"}],"steps":["掲示や担当者の説明を確認し、短いクイズで理解を振り返りましょう。"],"documents":[],"deadline":null,"phrases":[{"ja":"もう一度、説明していただけますか。","en":"Could you explain once more?"}],"dialogue":[],"roleplays":[]}','draft','2026-10-25T00:00:00Z' where not exists(select 1 from public.guide_translations where id='d8060000-0000-4000-8000-000000000011') on conflict do nothing;
insert into public.guide_translations(id,article_id,locale,title,summary,content,review_status,updated_at) select 'd8060000-0000-4000-8000-000000000012','d8030000-0000-4000-8000-000000000012','ja','住まいのルール','自分の契約と建物の掲示を読みます。別の建物のルールを当てはめず、分からないことは管理者に尋ねます。','{"sections":[{"id":"lesson","title":"住まいのルール","text":"自分の契約と建物の掲示を読みます。別の建物のルールを当てはめず、分からないことは管理者に尋ねます。","kind":"suggestion"}],"steps":["掲示や担当者の説明を確認し、短いクイズで理解を振り返りましょう。"],"documents":[],"deadline":null,"phrases":[{"ja":"もう一度、説明していただけますか。","en":"Could you explain once more?"}],"dialogue":[],"roleplays":[]}','draft','2026-10-25T00:00:00Z' where not exists(select 1 from public.guide_translations where id='d8060000-0000-4000-8000-000000000012') on conflict do nothing;
insert into public.guide_translations(id,article_id,locale,title,summary,content,review_status,updated_at) select 'd8060000-0000-4000-8000-000000000013','d8030000-0000-4000-8000-000000000013','ja','ごみの分別','自治体の分別案内・収集日と、建物の集積所を確認します。曜日や袋の決まりが全国共通とは限りません。','{"sections":[{"id":"lesson","title":"ごみの分別","text":"自治体の分別案内・収集日と、建物の集積所を確認します。曜日や袋の決まりが全国共通とは限りません。","kind":"municipal"}],"steps":["掲示や担当者の説明を確認し、短いクイズで理解を振り返りましょう。"],"documents":[],"deadline":null,"phrases":[{"ja":"もう一度、説明していただけますか。","en":"Could you explain once more?"}],"dialogue":[],"roleplays":[]}','draft','2026-10-25T00:00:00Z' where not exists(select 1 from public.guide_translations where id='d8060000-0000-4000-8000-000000000013') on conflict do nothing;
insert into public.guide_translations(id,article_id,locale,title,summary,content,review_status,updated_at) select 'd8060000-0000-4000-8000-000000000014','d8030000-0000-4000-8000-000000000014','ja','自転車と歩行の安全','公式の交通安全情報と現地の標識を確認します。この短い日本語練習は交通法規のすべてや運転方法を説明するものではありません。','{"sections":[{"id":"lesson","title":"自転車と歩行の安全","text":"公式の交通安全情報と現地の標識を確認します。この短い日本語練習は交通法規のすべてや運転方法を説明するものではありません。","kind":"law"}],"steps":["掲示や担当者の説明を確認し、短いクイズで理解を振り返りましょう。"],"documents":[],"deadline":null,"phrases":[{"ja":"もう一度、説明していただけますか。","en":"Could you explain once more?"}],"dialogue":[],"roleplays":[]}','draft','2026-10-25T00:00:00Z' where not exists(select 1 from public.guide_translations where id='d8060000-0000-4000-8000-000000000014') on conflict do nothing;
insert into public.guide_translations(id,article_id,locale,title,summary,content,review_status,updated_at) select 'd8060000-0000-4000-8000-000000000015','d8030000-0000-4000-8000-000000000015','ja','職場のマナー','職場の連絡・報告の方法を上司に確認します。職場の方針と法律上の義務は区別します。','{"sections":[{"id":"lesson","title":"職場のマナー","text":"職場の連絡・報告の方法を上司に確認します。職場の方針と法律上の義務は区別します。","kind":"workplace"}],"steps":["掲示や担当者の説明を確認し、短いクイズで理解を振り返りましょう。"],"documents":[],"deadline":null,"phrases":[{"ja":"もう一度、説明していただけますか。","en":"Could you explain once more?"}],"dialogue":[],"roleplays":[]}','draft','2026-10-25T00:00:00Z' where not exists(select 1 from public.guide_translations where id='d8060000-0000-4000-8000-000000000015') on conflict do nothing;
insert into public.guide_translations(id,article_id,locale,title,summary,content,review_status,updated_at) select 'd8060000-0000-4000-8000-000000000016','d8030000-0000-4000-8000-000000000016','ja','挨拶と伝え方','関係や場面に合う挨拶を選びます。丁寧な言い方が合う場合でも、カジュアルな文が文法的に誤りとは限りません。','{"sections":[{"id":"lesson","title":"挨拶と伝え方","text":"関係や場面に合う挨拶を選びます。丁寧な言い方が合う場合でも、カジュアルな文が文法的に誤りとは限りません。","kind":"culture"}],"steps":["掲示や担当者の説明を確認し、短いクイズで理解を振り返りましょう。"],"documents":[],"deadline":null,"phrases":[{"ja":"もう一度、説明していただけますか。","en":"Could you explain once more?"}],"dialogue":[],"roleplays":[]}','draft','2026-10-25T00:00:00Z' where not exists(select 1 from public.guide_translations where id='d8060000-0000-4000-8000-000000000016') on conflict do nothing;
insert into public.guide_translations(id,article_id,locale,title,summary,content,review_status,updated_at) select 'd8060000-0000-4000-8000-000000000017','d8030000-0000-4000-8000-000000000017','ja','文化と習慣','その場の様子を見て、分からないときは丁寧に尋ねます。習慣は人や場所で異なり、思い込みを一律の義務にしません。','{"sections":[{"id":"lesson","title":"文化と習慣","text":"その場の様子を見て、分からないときは丁寧に尋ねます。習慣は人や場所で異なり、思い込みを一律の義務にしません。","kind":"culture"}],"steps":["掲示や担当者の説明を確認し、短いクイズで理解を振り返りましょう。"],"documents":[],"deadline":null,"phrases":[{"ja":"もう一度、説明していただけますか。","en":"Could you explain once more?"}],"dialogue":[],"roleplays":[]}','draft','2026-10-25T00:00:00Z' where not exists(select 1 from public.guide_translations where id='d8060000-0000-4000-8000-000000000017') on conflict do nothing;
